/**
 * n8n Code node — Parse OpenAI "Message a model" output (new Responses shape)
 * Extracts: item.json.output[0].content[0].text
 * Returns: parsed note JSON at root, plus ok/meta helpers
 */

function extractJsonString(raw) {
  if (raw == null) return null;

  let s = String(raw).trim();

  // Remove ```json fences if present
  s = s.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "").trim();

  // Try direct object extraction
  const firstBrace = s.indexOf("{");
  const lastBrace = s.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return s.slice(firstBrace, lastBrace + 1).trim();
  }

  // Try array extraction
  const firstBracket = s.indexOf("[");
  const lastBracket = s.lastIndexOf("]");
  if (firstBracket !== -1 && lastBracket !== -1 && lastBracket > firstBracket) {
    return s.slice(firstBracket, lastBracket + 1).trim();
  }

  return null;
}

function safeJsonParseFromText(text) {
  const jsonStr = extractJsonString(text);
  if (!jsonStr) throw new Error("Could not locate JSON in model output text.");
  return JSON.parse(jsonStr);
}

return items.map((item) => {
  // ✅ This is the actual model text in your screenshot
  const text =
    item.json?.output?.[0]?.content?.[0]?.text ??
    item.json?.output?.[0]?.content?.find?.((c) => c?.type === "output_text")?.text ??
    item.json?.content ??
    item.json?.message?.content ??
    item.json?.text;

  try {
    const note = safeJsonParseFromText(text);

    return {
      json: {
        ok: true,
        ...note, // <-- IMPORTANT: put the note fields at the root for the UI
        meta: {
          ...(note.meta || {}),
          confidence_overall: note.meta?.confidence_overall || "",
        },
      },
    };
  } catch (e) {
    return {
      json: {
        ok: false,
        error: e.message,
        raw_preview: (text ? String(text).slice(0, 2000) : null),
      },
    };
  }
});

// Canonical preprocessor for clinical note workflows
const results = [];

for (const item of items) {
  const j = item.json ?? {};
  const outerBody = j.body ?? {};

  let inner = {};
  if (typeof outerBody.body === "string") {
    try {
      inner = JSON.parse(outerBody.body);
    } catch (e) {
      inner = {};
    }
  } else if (typeof outerBody.body === "object" && outerBody.body) {
    inner = outerBody.body;
  }

  // Combined body parameters
  const body = {
    ...outerBody,
    ...inner,
  };

  // Safely parse patient_clinical_context if present
  let patientData = {};
  const contextString = body.patient_clinical_context || j.patient_clinical_context;
  if (contextString) {
    try {
      patientData = typeof contextString === "string" ? JSON.parse(contextString) : contextString;
    } catch (e) {
      patientData = {};
    }
  }

  // Check binary audio presence
  const hasAudio = Boolean(item.binary && (item.binary.audio || item.binary.audio0 || item.binary.data));

  const agencyName = body.agency_name || body.facility_name || j.agency_name || j.facility_name || "";
  const caseManagerName = body.case_manager_name || body.provider_name || patientData.case_manager || body.case_manager || "";

  // Build clean root properties
  const normalizedJson = {
